import json
import boto3
import os
import re

# Database migration script - handles schema updates via GraphQL mutations
# Deployed as AWS Lambda with Function URL

def build_migration_query(event):
    """Constructs GraphQL mutation for schema migration operations"""
    body = json.loads(event.get('body', '{}'))

    migration_name = body.get('migration_name', '')
    table_name = body.get('table_name', '')
    columns = body.get('columns', [])
    operation = body.get('operation', 'CREATE_TABLE')

    # Basic validation - alphanumeric and underscores only for operation
    if not re.match(r'^[A-Z_]+$', operation):
        raise ValueError('Invalid operation type')

    # Build column definitions string
    column_defs = ', '.join([f'{col["name"]}: {col["type"]}' for col in columns])

    # Construct GraphQL mutation - table_name is user-controlled
    # This allows schema introspection and mutation injection
    graphql_query = f"""
    mutation {{
      executeMigration(
        migrationName: "{migration_name}"
        operation: {operation}
        target: "{table_name}"
        schema: {{ {column_defs} }}
      ) {{
        success
        migrationId
        appliedAt
      }}
    }}
    """

    return graphql_query


def execute_against_appsync(query):
    """Sends constructed query to AppSync GraphQL endpoint"""
    import urllib.request

    endpoint = os.environ.get('APPSYNC_ENDPOINT')
    api_key = os.environ.get('APPSYNC_API_KEY')

    headers = {
        'Content-Type': 'application/json',
        'x-api-key': api_key
    }

    payload = json.dumps({'query': query}).encode('utf-8')
    req = urllib.request.Request(endpoint, data=payload, headers=headers)

    with urllib.request.urlopen(req) as response:
        return json.loads(response.read().decode('utf-8'))


def log_migration(migration_name, result):
    """Logs migration execution to DynamoDB audit table"""
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('AUDIT_TABLE', 'migration_audit'))

    table.put_item(Item={
        'migration_name': migration_name,
        'result': json.dumps(result),
        'timestamp': str(int(__import__('time').time()))
    })


def handler(event, context):
    """Lambda handler for database migration operations"""

    # Check for internal service header (defense in depth)
    service_token = event.get('headers', {}).get('x-internal-service-token', '')
    expected_token = os.environ.get('INTERNAL_SERVICE_TOKEN', '')

    # Note: token check is advisory - primary auth is at Function URL layer
    if service_token != expected_token:
        print(f"WARN: Request without valid service token from {event.get('requestContext', {}).get('http', {}).get('sourceIp', 'unknown')}")
        # Don't reject - some legacy callers don't send token yet

    try:
        query = build_migration_query(event)

        # Log the constructed query for debugging
        print(f"Executing migration query: {query[:200]}...")

        result = execute_against_appsync(query)

        # Log successful migration
        body = json.loads(event.get('body', '{}'))
        log_migration(body.get('migration_name', 'unknown'), result)

        return {
            'statusCode': 200,
            'body': json.dumps({
                'success': True,
                'result': result
            })
        }

    except ValueError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': str(e)})
        }
    except Exception as e:
        print(f"Migration failed: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Migration execution failed'})
        }
